class Manifest(unittest.TestCase):
    """EVOL-061: the bump as a tool — the entry, its line, the frontmatter and the framework version in the checked shape; idempotent on the branch."""

    def _repo(self, tmp, project=False):
        repo = Path(tmp) / "r"; repo.mkdir(parents=True)
        subprocess.run(["git", "-C", str(repo), "init", "-q", "-b", "main"], check=True)
        subprocess.run(["git", "-C", str(repo), "config", "user.email", "t@t"], check=True); subprocess.run(["git", "-C", str(repo), "config", "user.name", "t"], check=True)
        mpath = "docs/project_log/governance_versions.json" if project else ".context/templates/setup/governance_versions.json"
        write(repo / "config/coherence-context.json", json.dumps({"context": "downstream" if project else "meta", "audit": {"root_sets": ["."], "exclusions": [".git/"], "manifest_paths": {"primary": mpath}}}))
        write(repo / mpath, json.dumps({k: v for k, v in MANIFEST_FIXTURE.items() if not (project and k in ("framework_core", "agent_templates"))}, indent=2))
        write(repo / "CLAUDE.md", "# x\n"); write(repo / ".claude/skills/x/SKILL.md", "---\nname: x\nversion: 1.4.0\n---\n# x\n"); write(repo / "scripts/gates/seal.py", "# s\n"); write(repo / ".context/templates/setup/scripts/gates/seal.py", "# s\n")
        write(repo / ".context/templates/setup/claude/agents/a.md", "# a\n")
        write(repo / (".claude/rules/x.md" if project else ".context/templates/setup/rules/x.md"), "---\nversion: \"2.1.0\"\n---\n# rule\n")
        write(repo / ".context/templates/po/t.md", "# t\n")
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True); subprocess.run(["git", "-C", str(repo), "commit", "-q", "-m", "base"], check=True)
        subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/EVOL-999-x"], check=True)
        return repo, repo / mpath

    def test_bump_moves_entry_line_frontmatter_and_framework(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo, mp = self._repo(tmp)
            r = manifest.bump(repo, ["CLAUDE.md", ".claude/skills/x/SKILL.md", ".context/templates/setup/rules/x.md"], "minor", "feat(EVOL-999) — the thing and why", framework="minor", base="main")
            m = json.loads(mp.read_text())
            self.assertEqual([x["to"] for x in r["moved"]], ["3.1.0", "1.5.0", "2.2.0"], "several entries in one call, each by the level — the skill resolved by `.claude/` + key, it carries no path")
            self.assertEqual(manifest.bump_version("1.4.7", "minor"), "1.5.0"); self.assertEqual(manifest.bump_version("2.3.4", "major"), "3.0.0"); self.assertEqual(manifest.bump_version("1.4.7", "patch"), "1.4.8")
            for bad in ("1.4", "v1.4.0", "1.4.0-rc1"):
                with self.assertRaisesRegex(GateFault, "not a version"):
                    manifest.bump_version(bad, "patch")
            self.assertEqual(m["framework_core"]["skills/x/SKILL.md"]["changelog"][0], "1.5.0: feat(EVOL-999) — the thing and why", "the line in the entry's shape, on top")
            self.assertIn("version: 1.5.0", (repo / ".claude/skills/x/SKILL.md").read_text()); self.assertIn('version: "2.2.0"', (repo / ".context/templates/setup/rules/x.md").read_text(), "the frontmatter moves with the entry, quoted or not")
            self.assertEqual((m["framework_version"], r["framework"]["to"]), ("1.3.0", "1.3.0")); self.assertTrue(m["description"].startswith("v1.3.0 (feature/EVOL-999-x): feat(EVOL-999) — the thing and why. "))
            self.assertEqual(m["last_updated"], dt.date.today().isoformat())
            self.assertEqual(manifest.check(repo, ["CLAUDE.md", ".claude/skills/x/SKILL.md", ".context/templates/setup/rules/x.md"], base="main", framework=True), [], "the check is green on what the helper wrote")
            # idempotent on the branch: the same call again changes nothing; a different note replaces the line, never the version
            before = mp.read_text()
            r2 = manifest.bump(repo, ["CLAUDE.md"], "minor", "feat(EVOL-999) — the thing and why", framework="minor", base="main")
            self.assertEqual((r2["moved"], len(r2["kept"]), r2["framework"].get("kept")), ([], 1, True)); self.assertEqual(mp.read_text(), before, "the same call twice changes nothing")
            r3 = manifest.bump(repo, ["CLAUDE.md"], "major", "feat(EVOL-999) — reworded", base="main")
            m = json.loads(mp.read_text()); self.assertEqual(m["framework_core"]["CLAUDE.md"]["version"], "3.1.0", "an entry already moved on the branch keeps its version whatever the level")
            self.assertEqual(m["framework_core"]["CLAUDE.md"]["changelog"][:2], ["3.1.0: feat(EVOL-999) — reworded", "3.0.0: feat — the base"], "the top line is replaced, the base line kept")
            self.assertEqual(r3["kept"][0]["line"], "3.1.0: feat(EVOL-999) — reworded")
            # the check's framework limb: entries moved, the framework not → red; moved → green
            manifest.bump(repo, [".context/templates/po/t.md"], "patch", "fix — a typo", base="main")
            self.assertEqual(manifest.check(repo, [".context/templates/po/t.md"], base="main", framework=True), [], "the framework moved with the first call")
            repo2, mp2 = self._repo(Path(tmp) / "b")
            manifest.bump(repo2, ["CLAUDE.md"], "patch", "fix — x", base="main")
            self.assertTrue(any("framework_version 1.2.0 did not advance" in x for x in manifest.check(repo2, ["CLAUDE.md"], base="main", framework=True)))
            manifest.bump(repo2, ["CLAUDE.md"], "patch", "fix — x", framework="patch", base="main")
            self.assertEqual(manifest.check(repo2, ["CLAUDE.md"], base="main", framework=True), [])
            # the default base: the branching grammar's diff base (origin/main) — a fault when it is not there, never a silent `every entry moves`
            before = mp2.read_text()
            with self.assertRaisesRegex(GateFault, "not on origin|cannot be read|no diff base"):
                manifest.bump(repo2, [".claude/skills/x/SKILL.md"], "minor", "feat — y")
            with self.assertRaisesRegex(GateFault, "not on origin|cannot be read|no diff base"):
                manifest.check(repo2, [".claude/skills/x/SKILL.md"])
            self.assertEqual(mp2.read_text(), before, "nothing written on the fault")
            subprocess.run(["git", "-C", str(repo2), "update-ref", "refs/remotes/origin/main", "main"], check=True)
            r4 = manifest.bump(repo2, [".claude/skills/x/SKILL.md"], "minor", "feat — y"); self.assertEqual(r4["base"], "diff base"); self.assertEqual(r4["moved"][0]["to"], "1.5.0")
            r5 = manifest.bump(repo2, [".claude/skills/x/SKILL.md"], "minor", "feat — y"); self.assertEqual((r5["moved"], len(r5["kept"])), ([], 1), "the default base holds idempotency")

    def test_new_entry_refusals_and_check(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo, mp = self._repo(tmp)
            with self.assertRaisesRegex(GateFault, "mandatory and never empty"):
                manifest.bump(repo, ["CLAUDE.md"], "patch", "   ", base="main")
            with self.assertRaisesRegex(GateFault, "matches no manifest entry"):
                manifest.bump(repo, ["scripts/nope.py"], "patch", "x", base="main")
            with self.assertRaisesRegex(GateFault, "--level must be one of"):
                manifest.bump(repo, ["CLAUDE.md"], "huge", "x", base="main")
            write(repo / "scripts/gates/new.py", "# new\n"); write(repo / ".context/templates/setup/scripts/gates/new.py", "# new\n")
            r = manifest.bump(repo, [], "minor", "feat(EVOL-999) — a new module", new=["scripts/gates/new.py", ".context/templates/setup/scripts/gates/new.py"], base="main")
            m = json.loads(mp.read_text())
            self.assertEqual([x["entry"] for x in r["added"]], ["framework_core:scripts/gates/new.py", "templates:scripts/gates/new.py"])
            self.assertEqual({k: m["framework_core"]["scripts/gates/new.py"][k] for k in ("version", "path", "changelog")}, {"version": "1.0.0", "path": "scripts/gates/new.py", "changelog": ["1.0.0: feat(EVOL-999) — a new module"]})
            self.assertEqual(m["templates"]["scripts/gates/new.py"]["target"], "scripts/gates/new.py"); self.assertEqual(m["templates"]["scripts/gates/new.py"]["content_type"], "universal")
            with self.assertRaisesRegex(GateFault, "already exists"):
                manifest.bump(repo, [], "minor", "x", new=["scripts/gates/new.py"], base="main")
            self.assertEqual((m["framework_core"]["scripts/gates/new.py"].get("delivery"), m["templates"]["scripts/gates/new.py"].get("delivery")), ("both", "both"), "a new gates module carries what its siblings carry (factory-sync ships by delivery)")
            self.assertNotIn("role", m["framework_core"]["scripts/gates/new.py"], "a sibling's prose is never copied")
            m2 = json.loads(mp.read_text()); m2["templates"]["scm/p.md"] = {"version": "1.0.0", "content_type": "universal", "target": "docs/scm/p.md", "stack_conditional": {"scm.platform": "GitHub"}, "role": "x", "changelog": ["1.0.0: added"]}; mp.write_text(json.dumps(m2))
            write(repo / ".context/templates/setup/scm/q.md", "# q\n")
            with self.assertRaisesRegex(GateFault, "pass --target"):
                manifest.bump(repo, [], None, "x", new=[".context/templates/setup/scm/q.md"], base="main")   # the sibling's target (docs/scm/p.md) names no convention
            manifest.bump(repo, [], None, "feat — q", new=[".context/templates/setup/scm/q.md"], base="main", target="docs/scm/q.md")
            q = json.loads(mp.read_text())["templates"]["scm/q.md"]
            self.assertNotIn("stack_conditional", q); self.assertNotIn("role", q); self.assertEqual(q["content_type"], "universal", "a new file ships everywhere until it says otherwise; no prose inherited")
            # an entry added on the branch is already moved: a later --entry keeps 1.0.0 and replaces the note
            r = manifest.bump(repo, ["scripts/gates/new.py"], "minor", "feat(EVOL-999) — a new module, reworded", base="main")
            self.assertEqual((r["moved"], r["kept"][0]["version"]), ([], "1.0.0")); self.assertEqual(json.loads(mp.read_text())["framework_core"]["scripts/gates/new.py"]["changelog"], ["1.0.0: feat(EVOL-999) — a new module, reworded"])
            # --new: the target by the nearest sibling's convention, the file must exist, the tree must be tracked, --level not owed
            write(repo / ".context/templates/setup/rules/y.md", "# y\n"); write(repo / ".context/templates/setup/claude/agents/b.md", "# b\n"); write(repo / ".context/templates/po/z.md", "# z\n"); write(repo / ".claude/skills/y/SKILL.md", "# y\n")
            r = manifest.bump(repo, [], None, "feat — new ones", new=[".context/templates/setup/rules/y.md", ".context/templates/setup/claude/agents/b.md", ".context/templates/po/z.md", ".claude/skills/y/SKILL.md"], base="main")
            m = json.loads(mp.read_text())
            self.assertEqual(m["templates"]["rules/y.md"]["target"], ".claude/rules/y.md"); self.assertEqual(m["templates"]["claude/agents/b.md"]["target"], ".claude/agents/b.md")
            self.assertEqual(m["agent_templates"]["po/z.md"]["target"], ".context/templates/po/z.md"); self.assertEqual(m["framework_core"]["skills/y/SKILL.md"]["path"], ".claude/skills/y/SKILL.md")
            self.assertEqual([x["target"] for x in r["added"]][0], ".claude/rules/y.md")
            with self.assertRaisesRegex(GateFault, "no such file"):
                manifest.bump(repo, [], None, "x", new=["scripts/typo.py"], base="main")
            write(repo / ".context/templates/setup/claude/x.md", "# x\n")
            manifest.bump(repo, [], None, "feat — x", new=[".context/templates/setup/claude/x.md"], base="main")
            self.assertEqual(json.loads(mp.read_text())["templates"]["claude/x.md"]["target"], ".claude/x.md", "a claude/* file follows the dominant convention (.claude/…); CLAUDE.md itself is the one exception, named with --target")
            write(repo / ".context/templates/setup/scm/r.md", "# r\n")
            with self.assertRaisesRegex(GateFault, "matches no manifest entry"):
                manifest.bump(repo, [".context/templates/setup/scm/r.md"], "patch", "x", new=[".context/templates/setup/scm/r.md"], base="main", target="docs/scm/r.md")   # --new X and --entry X in one call: X is not an entry yet
            # a frontmatter version line the shape does not read: the manifest moves, the file is said as NOT moved, the check says parity cannot be verified
            write(repo / ".claude/skills/x/SKILL.md", "---\nname: x\nversion: 1.4 # c\n---\n# x\n")
            r = manifest.bump(repo, [".claude/skills/x/SKILL.md"], "minor", "feat — z", base="main")
            self.assertEqual(r["frontmatter_skipped"], [{"file": ".claude/skills/x/SKILL.md", "reason": "unmatched"}]); self.assertIn("! frontmatter NOT moved (unmatched)", manifest.render(r))
            self.assertIn("version: 1.4 # c", (repo / ".claude/skills/x/SKILL.md").read_text(), "the file is untouched")
            self.assertTrue(any("cannot be read (unmatched)" in x for x in manifest.check(repo, [".claude/skills/x/SKILL.md"], base="main")))
            # a dry run writes nothing and says what it would do
            write(repo / ".claude/skills/x/SKILL.md", "---\nname: x\nversion: 1.5.0\n---\n# x\n")
            before_m, before_f = mp.read_text(), (repo / ".claude/skills/x/SKILL.md").read_text()
            r = manifest.bump(repo, ["CLAUDE.md"], "patch", "fix — dry", base="main", write=False)
            self.assertEqual((mp.read_text(), (repo / ".claude/skills/x/SKILL.md").read_text(), r["written"]), (before_m, before_f, False)); self.assertIn("dry run", manifest.render(r))
            write(repo / "docs/x.md", "# d\n")
            with self.assertRaisesRegex(GateFault, "outside every tracked tree"):
                manifest.bump(repo, [], None, "x", new=["docs/x.md"], base="main")
            write(repo / ".context/templates/setup/orphan/o.md", "# o\n")
            with self.assertRaisesRegex(GateFault, "pass --target"):
                manifest.bump(repo, [], None, "x", new=[".context/templates/setup/orphan/o.md"], base="main")
            r = manifest.bump(repo, [], None, "x", new=[".context/templates/setup/orphan/o.md"], base="main", target="docs/orphan/o.md")
            self.assertEqual(json.loads(mp.read_text())["templates"]["orphan/o.md"]["target"], "docs/orphan/o.md", "--target names it when no sibling tells")
            # atomic: a fault on the second entry writes nothing — the manifest and the first file stay as they were
            before_m, before_f = mp.read_text(), (repo / ".claude/skills/x/SKILL.md").read_text()
            with self.assertRaisesRegex(GateFault, "matches no manifest entry"):
                manifest.bump(repo, [".claude/skills/x/SKILL.md", "scripts/nope.py"], "minor", "x", base="main")
            self.assertEqual((mp.read_text(), (repo / ".claude/skills/x/SKILL.md").read_text()), (before_m, before_f), "nothing half-applied")
            # a base that cannot be read is a fault, never a silent `every entry moves`; --no-base is the one way on purpose
            with self.assertRaisesRegex(GateFault, "cannot be read"):
                manifest.bump(repo, ["CLAUDE.md"], "patch", "fix — x", base="nope-ref")
            with self.assertRaisesRegex(GateFault, "cannot be read"):
                manifest.check(repo, ["CLAUDE.md"], base="nope-ref")
            with self.assertRaisesRegex(GateFault, "nothing to check"):
                manifest.check(repo, [], base="main")
            with self.assertRaisesRegex(GateFault, "two things"):
                manifest.bump(repo, ["CLAUDE.md"], "patch", "x", base="main", no_base=True)
            r = manifest.bump(repo, ["CLAUDE.md", "framework_core:CLAUDE.md"], "patch", "fix — twice named", base="main")
            self.assertEqual(len(r["moved"]) + len(r["kept"]), 1); self.assertEqual(json.loads(mp.read_text())["framework_core"]["CLAUDE.md"]["changelog"].count("3.0.1: fix — twice named") + json.loads(mp.read_text())["framework_core"]["CLAUDE.md"]["changelog"].count("3.0.2: fix — twice named"), 1, "one entry named twice: one plan, one line")
            # the check is red before a bump and names the cure; green after
            problems = manifest.check(repo, [".context/templates/po/t.md"], base="main", framework=True)
            self.assertTrue(any("did not advance against the base (1.0.0)" in x for x in problems), problems)
            manifest.bump(repo, [".context/templates/po/t.md"], "patch", "fix — a typo", base="main")
            self.assertEqual(manifest.check(repo, [".context/templates/po/t.md"], base="main"), [])
            # frontmatter drift is a check finding (manifest-parity by construction when the helper wrote it; by hand it drifts)
            write(repo / ".claude/skills/x/SKILL.md", "---\nname: x\nversion: 9.9.9\n---\n# x\n")
            cur = json.loads(mp.read_text())["framework_core"]["skills/x/SKILL.md"]["version"]
            self.assertTrue(any(f"frontmatter version 9.9.9 ≠ manifest {cur}" in x for x in manifest.check(repo, [".claude/skills/x/SKILL.md"], base="main")))
            # --no-base: every entry moves, said in the result
            r = manifest.bump(repo, ["CLAUDE.md"], "patch", "fix — x", no_base=True); self.assertEqual(r["base"], "none (every entry moves — --no-base)"); self.assertEqual(r["moved"][0]["to"], "3.0.2", "CLAUDE.md at 3.0.1 from the twice-named case: with no base every entry moves, 3.0.1 → 3.0.2")

    def test_project_manifest_resolves_by_target(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo, mp = self._repo(tmp, project=True)
            r = manifest.bump(repo, [".claude/rules/x.md"], "patch", "fix(FEAT-1) — the rule's wording", base="main")
            m = json.loads(mp.read_text())
            self.assertEqual(r["moved"], [{"entry": "templates:rules/x.md", "from": "2.1.0", "to": "2.1.1"}], "a project resolves its file by the entry's target")
            self.assertIn('version: "2.1.1"', (repo / ".claude/rules/x.md").read_text())
            self.assertEqual(manifest.check(repo, ["templates:rules/x.md"], base="main"), [], "section:key names an entry directly")
            with self.assertRaisesRegex(GateFault, "framework repo's act"):
                manifest.bump(repo, [], None, "x", new=[".claude/rules/x.md"], base="main")
            with self.assertRaisesRegex(GateFault, "framework repo's act"):
                manifest.bump(repo, [".claude/rules/x.md"], "patch", "x", framework="patch", base="main")
            # a target shared by two entries is never an arbitrary pick
            m = json.loads(mp.read_text()); m["templates"]["rules/x2.md"] = dict(m["templates"]["rules/x.md"]); mp.write_text(json.dumps(m))
            with self.assertRaisesRegex(GateFault, "is the target of 2 entries"):
                manifest.bump(repo, [".claude/rules/x.md"], "patch", "x", base="main")


class Canary(unittest.TestCase):
    """EVOL-059: the lens canary — the fixture's own consistency, the judge red/green, the plan on model drift; red first."""

    def _repo(self, tmp):
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text()); q["agents"] = {"families": {"writer": "sonnet", "critic": "opus"}}
        write(repo / "config/quality.json", json.dumps(q)); write(repo / ".claude/rules/agents.md", RULE_AGENTS_LENSES)
        return repo

    @staticmethod
    def _return(lens, skip=(), sev="🔴", shift=0):
        lines = [f"{f}:{n + shift} · {sev} · confidence 90% · probe: read the diff" for it in canary.EXPECTED[lens] if it["id"] not in skip for f, n in it["at"][:1]]
        return "\n".join(lines) + "\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: claude-x\n"

    def test_fixture_is_consistent_and_invisible_at_rest(self):
        self.assertEqual(canary.consistency(), [], "every anchor is an added line, the planted credential carries its marker and is encoded at rest")
        diff = canary.fixture()
        self.assertIn("canary-secret", diff); self.assertIn("+++ b/src/orders/repo.py", diff)
        self.assertTrue(any("BILLING" in t and "canary-secret" in t for t in canary.added_lines(diff)["src/orders/repo.py"].values()), "the planted credential's own line carries the marker")
        added = canary.added_lines(diff)
        self.assertEqual(added["src/orders/repo.py"][9].strip()[:16], "rows = query(\"SE")
        self.assertEqual(added["docs/project_log/governance_versions.json"][7].strip()[:30], "\"1.2.0: feat(CAN-001) — the or")
        self.assertNotIn("sk-" + "canary", (HERE / "canary.py").read_text(encoding="utf-8"), "no scanner sees the planted credential in the repository")
        planted = canary.planted_credential()
        self.assertRegex(planted, r'^BILLING_API_KEY = "sk_' + r'live_[A-Za-z0-9]{32}"  # canary-secret$', "a shape real scanners flag (stripe-access-token)")
        val = planted.split('"')[1].removeprefix("sk_" + "live_")
        entropy = -sum(val.count(c) / len(val) * math.log2(val.count(c) / len(val)) for c in set(val))
        self.assertGreaterEqual(entropy, 3.5, "at gitleaks' generic-api-key entropy floor — the shape alone is not a detection")
        self.assertNotIn(planted.split('"')[1], (HERE / "canary.py").read_text(encoding="utf-8")); self.assertEqual(added["src/orders/repo.py"][23], planted)
        self.assertEqual(canary.LENS_AGENT.get("plan"), "factory-plan-critic", "EVOL-069: the plan critic is calibrated too")
        self.assertTrue(all(f == "docs/spec/CAN-001/increment_plan.md" for it in canary.EXPECTED["plan"] for f, _ in it["at"][:1]), "the plan lens's defects are planted in the plan")
        self.assertIn("PayFlow", added["docs/spec/CAN-001/increment_plan.md"][canary.EXPECTED["plan"][0]["at"][0][1]], "an external premise stated as verified")
        self.assertEqual(set(canary.EXPECTED), set(canary.LENSES)); self.assertTrue(all(len(v) >= 2 for v in canary.EXPECTED.values()), "at least two planted defects per lens")
        self.assertIn("c3", [i["id"] for i in canary.EXPECTED["correctness"]], "EVOL-068: an always-green test"); self.assertIn("f3", [i["id"] for i in canary.EXPECTED["fidelity"]], "EVOL-068: a deferral comment")
        self.assertIn("next slice", added["src/orders/repo.py"][canary.EXPECTED["fidelity"][2]["at"][0][1]]); self.assertEqual(added["tests/test_orders.py"][canary.EXPECTED["correctness"][2]["at"][0][1]].strip(), "assert out == out")
        self.assertEqual(agents.check_return(self._return("security"), "work-critic"), [], "the synthetic return is in the critic's own contract shape")

    def test_judge_green_red_and_tolerance(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            r = canary.judge(repo, "security", self._return("security"), "claude-x")
            self.assertTrue(r["ok"]); self.assertEqual(r["found"], ["s1", "s2"]); self.assertEqual(r["missed"], [])
            only_s1 = "src/orders/api.py:7 · 🟡 · confidence 80% · probe: tenant_id unused\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: claude-x\n"
            r = canary.judge(repo, "security", only_s1, "claude-x")
            self.assertFalse(r["ok"]); self.assertEqual(r["missed"], ["s2"]); self.assertIn("credential", r["reason"]); self.assertIn("never blocks", canary.render_judge(r))
            # both coordinate readings are accepted (the new file's, the diff text's) and never land on another anchor: the filler leading the diff keeps the two spaces apart
            self.assertEqual(canary.judge(repo, "security", self._return("security", skip=("s2",)), "claude-x")["missed"], ["s2"], "the query alone never credits the credential, in either reading")
            self.assertEqual(canary.judge(repo, "security", "src/orders/repo.py:10 · 🔴 · confidence 95% · probe: read\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: m\n", "m")["missed"], ["s2"], "a line between the two anchors credits one, never both")
            for bad in ({"judged": [], "seen": {}}, {"judged": {"security": "x"}, "seen": {}}, {"judged": {}, "seen": {"fidelity": 3}}):
                write(repo / ".claude/state/canary.json", json.dumps(bad))
                with self.assertRaisesRegex(GateFault, "record's shape"):
                    canary.plan(repo)
            (repo / ".claude/state/canary.json").unlink()
            # the gap between the two coordinate spaces is judged against the project's tolerance
            self.assertEqual(canary.consistency(repo), [])
            write(repo / ".claude/rules/agents.md", RULE_AGENTS_LENSES.replace("canary: {line_tolerance: 3}", "canary: {line_tolerance: 40}"))
            wide = canary.consistency(repo)
            self.assertTrue(any("within reach of the new file's numbering" in x for x in wide), "a tolerance wider than the filler is a finding")
            self.assertTrue(any("reaches two planted defects" in x for x in wide), "both checks fire at a tolerance that breaks both promises — no early return")
            write(repo / ".claude/rules/agents.md", RULE_AGENTS_LENSES.replace("canary: {line_tolerance: 3}", "canary: {line_tolerance: 7}"))
            self.assertTrue(any("reaches two planted defects of the security lens" in x for x in canary.consistency(repo)), "a tolerance that reaches two anchors of one lens is a finding (repo.py 9 and 23 are 14 apart)")
            between = "src/orders/repo.py:16 · 🔴 · confidence 95% · probe: read\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: m\n"
            with self.assertRaisesRegex(GateFault, "inconsistent under this project's policy"):
                canary.judge(repo, "security", between, "m")   # one finding between the two anchors would credit both: never a verdict
            self.assertNotIn("security", canary.read_record(repo)["judged"], "a refused judge leaves no verdict on record")
            r = agents.resolve(repo, "work-critic", surface="security"); self.assertEqual(r["canary_owed"], []); self.assertIn("reaches two planted defects", r["canary_fault"], "the fault names its cause")
            p = canary.plan(repo); self.assertEqual(p["owed"], []); self.assertIn("reaches two planted defects", p["fault"]); self.assertFalse(p["fixture_ok"], "one definition: the plan owes nothing on a fixture the judge would refuse")
            self.assertTrue(canary.render_plan(p).startswith("canary: FAULT — nothing owed until the fault below is cured"), "the header tells the truth: a fault, not `nothing owed — every lens judged`"); self.assertIn("\n  ✗ " + p["fault"], canary.render_plan(p), "the ✗ line is the fault itself, cause included")
            write(repo / ".claude/rules/agents.md", RULE_AGENTS_LENSES.replace("canary: {line_tolerance: 3}", "canary: {line_tolerance: 6}"))
            self.assertEqual(canary.judge(repo, "security", between, "m")["missed"], ["s1", "s2"], "under the widest sound tolerance a line between the anchors credits neither")
            write(repo / ".claude/rules/agents.md", RULE_AGENTS_LENSES)
            with self.assertRaisesRegex(GateFault, "no finding in the contract shape"):
                canary.judge(repo, "security", "no findings — clean\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: m\n", "m")   # trailing text is not the contract's line
            self.assertEqual(canary.judge(repo, "security", "- No findings.\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: m\n", "m")["missed"], ["s1", "s2"], "the bulleted form is the contract's line")
            for txt in ("- No findings.\n", "no findings — clean\n"):   # the two readers of `no findings` agree: what the contract check admits, the judge judges; what it refuses, the judge faults
                gov = "## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: m\n"
                admitted = agents.check_return(txt + gov, "work-critic") == []
                try:
                    canary.judge(repo, "security", txt + gov, "m"); judged = True
                except GateFault:
                    judged = False
                self.assertEqual(admitted, judged, txt)
            absolute = "/somewhere/else/src/orders/repo.py:9 · 🔴 · confidence 95% · probe: read\n/somewhere/src/orders/repo.py:23 · 🔴 · confidence 95% · probe: read\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: m\n"
            self.assertTrue(canary.judge(repo, "security", absolute, "m")["ok"], "an absolute path still names the file by its tail")
            self.assertEqual(canary.judge(repo, "security", absolute.replace("/somewhere/else/src/orders/repo.py", "xsrc/orders/repo.py"), "m")["missed"], ["s1"], "a tail without its slash is another file")
            with self.assertRaisesRegex(GateFault, "no finding in the contract shape"):
                canary.judge(repo, "security", "I looked and it seems fine.\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: m\n", "m")
            self.assertEqual(canary.judge(repo, "security", "no findings\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: m\n", "m")["missed"], ["s1", "s2"], "an honest `no findings` is a verdict: everything missed")
            # the no-overlap guard goes red when an anchor sits within the diff text's range; the roster check when a lens's agent is missing
            saved = canary.EXPECTED["security"][0]["at"]
            try:
                canary.EXPECTED["security"][0]["at"] = [["src/orders/repo.py", 60]]
                self.assertTrue(any("within reach of the new file's numbering" in x for x in canary.consistency()), "the guard is not a tautology")
                canary.EXPECTED["security"][0]["at"] = [["README.md", 6]]   # an anchor on the filler: its new-file numbering runs to 40 and its diff-text lines start at 6 — the bound is the file's length, not the anchor
                self.assertTrue(any("within reach of the new file's numbering (to 40" in x for x in canary.consistency()), "the bound is the longest anchored file's numbering")
            finally:
                canary.EXPECTED["security"][0]["at"] = saved
            write(repo / ".claude/rules/agents.md", RULE_AGENTS_LENSES.replace("    - {name: factory-critic-security, class: work-critic, lens: security, surface: [\"**\"]}\n", ""))
            self.assertTrue(any("factory-critic-security is not in the roster" in x for x in canary.consistency(repo)))
            write(repo / ".claude/rules/agents.md", "\n".join(l for l in RULE_AGENTS_LENSES.splitlines() if not l.startswith("    - {name: factory-")) + "\n")   # `roster:` with no entries reads as null
            null_roster = [x for x in canary.consistency(repo) if "agents.roster is not a list" in x]
            self.assertEqual(len(null_roster), 1, "a null roster is one finding, said once, never a crash"); self.assertTrue(null_roster[0].startswith("rules/agents.md: "), "a fault naming no config file is filed under the rule")
            with self.assertRaisesRegex(GateFault, "roster is not a list"):
                agents.resolve(repo, "work-critic", surface="security")   # a policy without a roster is no policy: the one reader fails closed for every consumer, the agents gate names it
            with self.assertRaisesRegex(GateFault, "roster is not a list"):
                agents.validate(repo)
            write(repo / ".claude/rules/agents.md", RULE_AGENTS_LENSES)
            self.assertEqual(canary.seen(repo, "security", "")["model"], "unknown", "an empty id is unknown — the lens stays owed")
            if (HERE.parent.parent / ".context/templates/setup").is_dir():   # the framework repo: the no-repo check reads the template's value — pinned here, skipped in a materialised project (which carries no template tree)
                template_rule = HERE.parent.parent / ".context/templates/setup/rules/agents.md"
                self.assertTrue(template_rule.is_file(), "the template rule moved — the pin must follow it")
                self.assertEqual(read_frontmatter(template_rule)["agents"]["canary"]["line_tolerance"], canary.DEFAULT_TOLERANCE)
            self.assertTrue(canary.judge(repo, "governance", self._return("governance", shift=3), "m")["ok"], "within the tolerance window")
            for lens, planted in (("correctness", "c3"), ("fidelity", "f3")):
                r = canary.judge(repo, lens, self._return(lens, skip=(planted,)), "m"); self.assertEqual(r["missed"], [planted], f"a return that misses {planted} reports it")
            self.assertEqual(canary.judge(repo, "governance", self._return("governance", shift=4), "m")["missed"], ["g1", "g2"], "beyond the window: missed")
            self.assertEqual(canary.judge(repo, "fidelity", self._return("fidelity", sev="🟢"), "m")["missed"], ["f1", "f2", "f3"], "a planted defect reported as informational is missed — the bar is above informational")
            alt = "src/orders/api.py:7 · 🟡 · confidence 80% · probe: read\nb/src/orders/repo.py:23 · 🔴 · confidence 95% · probe: read\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: m\n"
            self.assertTrue(canary.judge(repo, "security", alt, "m")["ok"], "a finding at an alternative anchor counts")
            pos: dict = {}; canary.added_lines(canary.fixture(), pos)
            by_diff = "src/orders/repo.py:%d · 🔴 · confidence 95%% · probe: read\nsrc/orders/repo.py:%d · 🔴 · confidence 95%% · probe: read\n## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\nInformational: 0\nModel: m\n" % (
                next(d for d, n in pos["src/orders/repo.py"].items() if n == 9), next(d for d, n in pos["src/orders/repo.py"].items() if n == 23))
            r = canary.judge(repo, "security", by_diff, "m"); self.assertTrue(r["ok"], "a critic that numbered the diff text's own lines is read in both coordinates (seen on the lowest rung)")
            self.assertEqual(r["findings"], 2, "a finding is counted once whatever its readings (a second append per reading gave four)")
            self.assertTrue(canary.judge(repo, "security", by_diff.replace("src/orders/repo.py:", "/somewhere/src/orders/repo.py:"), "m")["ok"], "an absolute path numbered by the diff text is mapped like the fixture's own path — never a false red")
            with self.assertRaisesRegex(GateFault, "needs --model"):
                canary.judge(repo, "security", self._return("security"), "")
            with self.assertRaisesRegex(GateFault, "not one of"):
                canary.judge(repo, "style", "x", "m")
            rec = canary.read_record(repo); self.assertEqual(rec["judged"]["security"]["model"], "m"); self.assertEqual(rec["judged"]["fidelity"]["missed"], ["f1", "f2", "f3"])
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace("  canary: {line_tolerance: 3}\n", ""))
            with self.assertRaisesRegex(GateFault, "line_tolerance"):
                canary.judge(repo, "security", self._return("security"), "m")

    def test_plan_owes_on_drift_never_judged_and_on_demand(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            p = canary.plan(repo); self.assertEqual(p["owed"], list(canary.LENSES), "never judged: every lens is owed"); self.assertTrue(p["fixture_ok"])
            for lens in canary.LENSES:
                canary.judge(repo, lens, self._return(lens), "claude-a"); canary.seen(repo, lens, "claude-a")
            self.assertEqual(canary.plan(repo)["owed"], [], "judged on the model it last ran on: nothing owed")
            canary.seen(repo, "security", "claude-b")
            p = canary.plan(repo); self.assertEqual(p["owed"], ["security"]); self.assertIn("the model moved", p["lenses"]["security"]["reason"]); self.assertIn("→ security", canary.render_plan(p))
            canary.seen(repo, "security", "unknown"); self.assertIn("the model is unknown", canary.plan(repo)["lenses"]["security"]["reason"], "a return that stated no id is said as such, never as a move")
            # judged on no id, before any seen (a fresh project whose harness states none): owed for that reason; seen on a known id afterwards: still that reason, never a move
            write(repo / ".claude/state/canary.json", json.dumps({"judged": {}, "seen": {}})); canary.judge(repo, "security", self._return("security"), "unknown")
            p = canary.plan(repo); self.assertEqual(p["owed"], list(canary.LENSES)); self.assertIn("the model is unknown", p["lenses"]["security"]["reason"], "judged on no id: owed, said as unknown")
            canary.seen(repo, "security", "claude-a"); self.assertIn("the model is unknown", canary.plan(repo)["lenses"]["security"]["reason"], "judged on no id, then seen on a known one: unknown, never a move")
            for lens in canary.LENSES:
                canary.judge(repo, lens, self._return(lens), "claude-a"); canary.seen(repo, lens, "claude-a")
            canary.seen(repo, "security", "claude-a"); canary.seen(repo, "fidelity", "unknown")
            self.assertEqual(canary.plan(repo)["owed"], ["fidelity"], "an unknown model keeps the lens owed")
            canary.seen(repo, "fidelity", "claude-a")
            self.assertEqual(canary.plan(repo, all_=True)["owed"], list(canary.LENSES), "on demand: every lens")
            write(repo / ".claude/state/canary.json", "{nope")
            with self.assertRaisesRegex(GateFault, "unreadable"):
                canary.plan(repo)


class Digests(unittest.TestCase):
    """EVOL-051: the loop checks what the push checks — every planning artefact of the feature carries a current, complete governance digest."""

    def _repo(self, tmp):
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text())
        q["documentation"] = {"paths": ["**/*.md", "docs/**"], "exclusions": []}
        q["verification"] = {"seal": {"required": False, "reason": "n/a"}, "gates": {}, "digest_artefacts": ["design.md", "dev_plan.md"]}
        write(repo / "config/quality.json", json.dumps(q))
        write(repo / ".context/governance_snapshot.md", "---\nconstitution_hash: abcdef1234567890\nsetup_hash: x\n---\n")
        write(repo / ".claude/rules/security_policy.md", "---\ndescription: s\napplicable_when:\n  path_glob: [\"src/**\"]\n---\n")
        write(repo / ".claude/rules/testing.md", "---\ndescription: t\napplicable_when:\n  always: true\n---\n")
        write(repo / ".claude/rules/ci-cd.md", "---\ndescription: c\napplicable_when:\n  path_glob: [\".github/workflows/**\"]\n---\n")
        write(repo / ".github/workflows/ci.yml", "on: push\n")
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "base"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "branch", "-M", "main"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "checkout", "-qb", "feature/FEAT-001-x"], check=True, capture_output=True)
        return repo

    def _commit(self, repo, msg="c"):
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", msg], check=True, capture_output=True)

    def test_digest_currency_and_completeness(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            self.assertEqual(digests.feature_id("feature/FEAT-001-x"), "FEAT-001"); self.assertEqual(digests.feature_id("feature/FEAT-001-inc-1-x-sub-2"), "FEAT-001"); self.assertIsNone(digests.feature_id("fix/x"))
            self.assertEqual(digests.fingerprint(repo), "abcdef12")
            r = digests.check(repo, "main"); self.assertTrue(r["ok"]); self.assertIn("nothing to judge", r["reason"])
            # an empty change binds the always-on rules only — never the whole tree (ci-cd is NOT bound: no workflow changed)
            self.assertNotIn("ci-cd", digests.bound_rules(repo, "main")); self.assertIn("testing", digests.bound_rules(repo, "main"))
            # the change on DISK binds — the static round runs before the commit
            write(repo / "src/app.py", "print(2)\n")
            self.assertIn("security_policy", digests.bound_rules(repo, "main"), "an uncommitted src change binds security_policy")
            # completeness is a REFERENCE (rules/<name>.md), never a bare word in prose
            write(repo / "docs/spec/FEAT-001/design.md", "---\ngovernance_digest_version: \"abcdef12\"\n---\n## 7. GCD\nWe defer testing to QA; security_policy applies.\n```\nrules/testing.md\n```\n")
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("incomplete", r["artefacts"][0]["reason"]); self.assertIn("testing", r["artefacts"][0]["reason"]); self.assertIn("security_policy", r["artefacts"][0]["reason"])
            write(repo / "docs/spec/FEAT-001/design.md", "---\ngovernance_digest_version: \"abcdef12\"\n---\n## 7. GCD\n" + "".join(f"- rules/{r}.md\n" for r in digests.bound_rules(repo, "main")))
            r = digests.check(repo, "main"); self.assertTrue(r["ok"], r)
            self._commit(repo, "code + design")
            r = digests.check(repo, "main"); self.assertTrue(r["ok"], r)
            # a stale fingerprint; at CI the fingerprint is n/a (no snapshot on the runner), completeness still judged
            write(repo / ".context/governance_snapshot.md", "---\nconstitution_hash: 9999999999\n---\n")
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("stale", r["artefacts"][0]["reason"])
            r = digests.check(repo, "main", control_point="ci"); self.assertTrue(r["ok"], r); self.assertIn("fingerprint n/a at ci", r["reason"])
            write(repo / ".context/governance_snapshot.md", "---\nconstitution_hash: abcdef1234567890\n---\n")
            # THE red the issue asks for: a corpus item appears (a new rule bound to this surface) — an UNTOUCHED artefact's digest is incomplete
            write(repo / ".claude/rules/privacy.md", "---\ndescription: p\napplicable_when:\n  path_glob: [\"src/**\"]\n---\n")
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("incomplete", r["artefacts"][0]["reason"]); self.assertIn("privacy", r["artefacts"][0]["reason"])
            (repo / ".claude/rules/privacy.md").unlink()
            # a second artefact without any digest; a missing snapshot downstream is RED (governance not delivered), never a fault the push walks past
            write(repo / "docs/spec/FEAT-001/dev_plan.md", "---\nstatus: READY\n---\n- rules/security_policy.md\n- rules/testing.md\n")
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("never generated", [a for a in r["artefacts"] if a["artefact"].endswith("dev_plan.md")][0]["reason"])
            self.assertIn("✗ docs/spec/FEAT-001/dev_plan.md", digests.render(r))
            (repo / ".context/governance_snapshot.md").unlink()
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("governance_snapshot.md is missing", r["artefacts"][0]["reason"])
            q = json.loads((repo / "config/quality.json").read_text()); del q["verification"]; write(repo / "config/quality.json", json.dumps(q))
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("`verification` is missing", r["reason"]); self.assertIn("RED", digests.render(r))



class Traceability(unittest.TestCase):
    """EVOL-053: one machine-readable home for the case → test link — strict ids, case → test, a shrink-only baseline."""

    PLAN = """---\nid: FEAT-001\nstatus: APPROVED\n---\n# Test Cases\n\n## 1. Acceptance\n| ID | Gherkin Ref | Business Scenario | Expected |\n|----|---|---|---|\n| AC-01 | Happy path | Login | Dashboard |\n\n## 2. Technical\n| ID | Type | Technical Scenario | Input | Expected |\n|----|---|---|---|---|\n| TC-01 | Edge | DB timeout | down | 503 |\n| TC-API-01 | /login | POST | ok | 200 |\n\n## 3. Standards (not cases)\n| Standard | Notes |\n|---|---|\n| ISO-8601 | dates |\n| HTTP-401 | unauthenticated |\n\n```markdown\n| ID | Type |\n|---|---|\n| TC-99 | a sample inside a fence declares nothing |\n```\n"""

    def _repo(self, tmp, kind="pytest-marker", required=True):
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text())
        q["traceability"] = {"required": required, "reason": "" if required else "no plans here", "home": {"kind": kind}, "plans": "docs/spec/*/test_plan.md",
                             "test_roots": ["tests/**", "src/**/*.test.*", "src/test/**"], "baseline": "docs/project_log/traceability_baseline.json"}
        write(repo / "config/quality.json", json.dumps(q))
        write(repo / "docs/spec/FEAT-001/test_plan.md", self.PLAN)
        self._commit(repo, "plan")
        return repo

    def _commit(self, repo, msg="c"):
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", msg, "--allow-empty"], check=True, capture_output=True)

    def test_declared_links_and_the_ratchet(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            c = traceability.cfg(repo)
            dec, bad = traceability.declared(repo, c)
            self.assertEqual(sorted(dec), ["FEAT-001/AC-01", "FEAT-001/TC-01", "FEAT-001/TC-API-01"], "only ID tables outside fences declare; a standards table is not a plan")
            self.assertEqual(bad, [])
            # no test yet: every case unlinked, none in the baseline → red, each named; --init refuses when NOTHING links (a misconfiguration, not debt)
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertEqual(r["unlinked"], sorted(dec)); self.assertEqual(len(r["new_debt"]), 3)
            with self.assertRaisesRegex(GateFault, "no test links any"):
                traceability.baseline(repo, init=True)
            # an UNTRACKED test on disk links (the static round runs before git add); a comment or a docstring is text, not a marker
            write(repo / "tests/test_login.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/AC-01")\ndef test_login(): pass\n\n# @pytest.mark.case("FEAT-001/TC-01")\ndef test_commented():\n    """@pytest.mark.case("FEAT-001/TC-API-01") lives in a docstring: not a marker"""\n    pass\n')
            r = traceability.check(repo); self.assertEqual(r["linked"], 1); self.assertIn("FEAT-001/TC-01", r["unlinked"]); self.assertIn("FEAT-001/TC-API-01", r["unlinked"])
            # the baseline records the debt ONCE; the file must be committed (CI reads the commit); then green with the debt on the board
            b = traceability.baseline(repo, init=True); self.assertEqual(b["unlinked"], ["FEAT-001/TC-01", "FEAT-001/TC-API-01"]); self.assertIn("commit", b["note"])
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertTrue(any("git does not track it" in f["reason"] for f in r["findings"]))
            self._commit(repo, "baseline + test")
            with self.assertRaisesRegex(GateFault, "only shrinks"):
                traceability.baseline(repo, init=True)
            r = traceability.check(repo); self.assertTrue(r["ok"], r["findings"]); self.assertEqual(r["linked"], 1)
            self.assertEqual({x["id"]: x["status"] for x in r["cases"]}, {"FEAT-001/AC-01": "linked", "FEAT-001/TC-01": "unlinked-baseline", "FEAT-001/TC-API-01": "unlinked-baseline"})
            self.assertEqual([x["tests"] for x in r["cases"] if x["id"] == "FEAT-001/AC-01"], [["tests/test_login.py:3"]], "QA reads the linked test from the gate, never re-derives it")
            # more marker forms: a class marker, the module's pytestmark, `from pytest import mark`, pytest.param(marks=…); a skipped test proves no case
            write(repo / "tests/test_more.py", 'import pytest\nfrom pytest import mark\n\npytestmark = pytest.mark.case("FEAT-001/TC-01")\n\n@mark.case("FEAT-001/TC-API-01")\nclass TestApi:\n    def test_ok(self): pass\n\n@pytest.mark.skip(reason="wip")\n@pytest.mark.case("FEAT-001/AC-01")\ndef test_skipped(): pass\n')
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertEqual(r["shrink"], ["FEAT-001/TC-01", "FEAT-001/TC-API-01"]); self.assertEqual(r["linked"], 3)
            self.assertEqual([x["tests"] for x in r["cases"] if x["id"] == "FEAT-001/AC-01"], [["tests/test_login.py:3"]], "the skipped test is not a link")
            b = traceability.baseline(repo, refresh=True); self.assertEqual(b["removed"], ["FEAT-001/TC-01", "FEAT-001/TC-API-01"]); self.assertEqual(b["unlinked"], [])
            self._commit(repo, "linked"); r = traceability.check(repo); self.assertTrue(r["ok"], r["findings"])
            # a NEW case declared after the baseline must link — the baseline never grows; a MANUAL case (Tool: Manual …) is never owed
            write(repo / "docs/spec/FEAT-001/test_plan.md", self.PLAN + "\n## 4. UX\n| ID | Test Case | Tool | Expected |\n|---|---|---|---|\n| UX-01 | Responsive | Manual + Lighthouse | adapts |\n| TC-02 | Edge | pytest | 200 |\n")
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertEqual(r["new_debt"], ["FEAT-001/TC-02"]); self.assertEqual(r["manual"], 1)
            self.assertEqual([x["status"] for x in r["cases"] if x["id"] == "FEAT-001/UX-01"], ["manual"])
            b = traceability.baseline(repo, refresh=True); self.assertEqual(b["unlinked"], [], "refresh never adds")
            write(repo / "tests/test_cache.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/TC-02")\ndef test_cache(): pass\n')
            self._commit(repo, "tc-02"); self.assertTrue(traceability.check(repo)["ok"])
            # a case → test link is required; test → case never is: a helper test with no marker is not a finding; a conftest is never scanned
            write(repo / "tests/test_helper.py", "def test_helper(): pass\n"); write(repo / "tests/conftest.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/AC-01")\ndef fixture_like(): pass\n')
            r = traceability.check(repo); self.assertTrue(r["ok"], r["findings"]); self.assertEqual([x["tests"] for x in r["cases"] if x["id"] == "FEAT-001/AC-01"], [["tests/test_login.py:3"]])
            # an unknown link is as wrong as a case with no test; a malformed id is red; an unparseable test file is red
            write(repo / "tests/test_bad.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/TC-99")\ndef test_ghost(): pass\n\n@pytest.mark.case("tc01")\ndef test_typo(): pass\n')
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertEqual(r["unknown"], ["FEAT-001/TC-99"])
            self.assertEqual(sorted(f["path"] for f in r["findings"]), ["tests/test_bad.py:3", "tests/test_bad.py:6"])
            write(repo / "tests/test_bad.py", "def broken(:\n")
            r = traceability.check(repo); self.assertTrue(any("does not parse" in f["reason"] for f in r["findings"]))
            (repo / "tests/test_bad.py").unlink()
            # a tracked test deleted on disk is simply gone (never a crash): its case is unlinked again
            (repo / "tests/test_cache.py").unlink()
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertEqual(r["new_debt"], ["FEAT-001/TC-02"])
            self._commit(repo, "tc-02 test gone")
            # a stale baseline entry (its case gone from the plan) is red until removed; a duplicate row is red; a grammar-failing id in an ID table is red
            write(repo / "docs/project_log/traceability_baseline.json", json.dumps({"unlinked": ["FEAT-001/TC-02", "FEAT-001/GONE-01"]}))
            r = traceability.check(repo); self.assertEqual(r["stale"], ["FEAT-001/GONE-01"])
            b = traceability.baseline(repo, refresh=True); self.assertEqual(b["unlinked"], ["FEAT-001/TC-02"]); self._commit(repo, "baseline")
            self.assertTrue(traceability.check(repo)["ok"])
            write(repo / "docs/spec/FEAT-001/test_plan.md", self.PLAN + "\n| ID | Type |\n|---|---|\n| TC-01 | again |\n| TC-1 | x |\n")
            r = traceability.check(repo)
            self.assertTrue(any("declared twice" in f["reason"] for f in r["findings"])); self.assertTrue(any("fails the grammar" in f["reason"] for f in r["findings"]))
            # a plans glob that names nothing while a plan exists is red; no plan at all is ok ("no test plan declares a case yet")
            q = json.loads((repo / "config/quality.json").read_text()); q["traceability"]["plans"] = "docs/plans/*/test_plan.md"; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertTrue(any("matches nothing while a test plan exists" in f["reason"] for f in r["findings"]))
            (repo / "docs/spec/FEAT-001/test_plan.md").unlink(); (repo / "docs/project_log/traceability_baseline.json").unlink(); self._commit(repo, "no plan")
            q["traceability"]["plans"] = "docs/spec/*/test_plan.md"; write(repo / "config/quality.json", json.dumps(q))
            for f in (repo / "tests").glob("test_*.py"):
                f.unlink()
            r = traceability.check(repo); self.assertTrue(r["ok"]); self.assertIn("no test plan declares", r["reason"])
            # a corrupt baseline is a fault; a missing config block is RED, never a fault; not required = n/a with its reason, red without one
            write(repo / "docs/project_log/traceability_baseline.json", "{nope")
            with self.assertRaisesRegex(GateFault, "unreadable"):
                traceability.check(repo)
            (repo / "docs/project_log/traceability_baseline.json").unlink()
            q["traceability"]["required"] = False; q["traceability"]["reason"] = ""; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertIn("without a `reason`", r["reason"])
            q["traceability"]["reason"] = "no plans here"; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertTrue(r["ok"]); self.assertFalse(r["required"]); self.assertIn("n/a", traceability.render(r))
            del q["traceability"]; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertIn("`traceability` is missing", r["reason"])

    def test_title_tag_and_junit_homes(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, kind="title-tag")
            write(repo / "src/login.test.ts", 'import { test } from "vitest";\ntest("[FEAT-001/AC-01] logs in", () => {});\nit.only("[FEAT-001/TC-01] times out", () => {});\ndescribe("[FEAT-001/TC-API-01] POST /login", () => { it("ok", () => {}); });\n// test("[FEAT-001/TC-API-01] commented out", () => {});\ntest.skip("[FEAT-001/TC-API-01] skipped", () => {});\n')
            r = traceability.check(repo); self.assertEqual(r["linked"], 2, "a describe, a comment and a skipped test link nothing"); self.assertEqual(r["unlinked"], ["FEAT-001/TC-API-01"])
            write(repo / "src/api.test.ts", 'test.each([1, 2])("[FEAT-001/TC-API-01] status %i", (i) => {});\n')
            r = traceability.check(repo); self.assertEqual(r["linked"], 3, "test.each links")
            write(repo / "src/other.test.ts", 'test("[FEAT-001/tc-01] lower", () => {});\n')
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertTrue(any("is not a case link" in f["reason"] for f in r["findings"]))
            (repo / "src/other.test.ts").unlink()
            # JUnit: @DisplayName is the home
            q = json.loads((repo / "config/quality.json").read_text()); q["traceability"]["home"] = {"kind": "junit-displayname"}; write(repo / "config/quality.json", json.dumps(q))
            write(repo / "src/test/LoginTest.java", 'class LoginTest {\n  @Test\n  @DisplayName("[FEAT-001/AC-01] logs in")\n  void login() {}\n  // @DisplayName("[FEAT-001/TC-01] commented")\n}\n')
            r = traceability.check(repo); self.assertEqual([x["status"] for x in r["cases"] if x["id"] == "FEAT-001/AC-01"], ["linked"]); self.assertIn("FEAT-001/TC-01", r["unlinked"])
            # custom: a pattern with a named group id is the ONLY home; an unknown kind is red
            q["traceability"]["home"] = {"kind": "custom"}; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertIn("needs a `pattern`", r["reason"])
            q["traceability"]["home"] = {"kind": "custom", "pattern": "case=(?P<id>[^ ]+)"}; write(repo / "config/quality.json", json.dumps(q))
            write(repo / "src/test/x.swift", "// case=FEAT-001/TC-01\n")
            r = traceability.check(repo); self.assertEqual([x["id"] for x in r["cases"] if x["status"] == "linked"], ["FEAT-001/TC-01"], "a custom home scans every text file under the roots")
            q["traceability"]["home"] = {"kind": "nope"}; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertIn("not one of", r["reason"])

    def test_pytest_plugin_refuses_collection_on_an_unknown_id(self):
        if not importlib.util.find_spec("pytest"):
            if os.environ.get("CI"):
                self.fail("pytest is not installed on the CI runner — the collection plugin's red must run there (governance-check.yml installs pytest)")
            self.skipTest("pytest is not installed here")
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            import shutil
            (repo / "tests").mkdir(exist_ok=True); (repo / "scripts").mkdir(exist_ok=True)
            shutil.copy(HERE.parent / "gate.py", repo / "scripts/gate.py"); shutil.copytree(HERE, repo / "scripts/gates", ignore=shutil.ignore_patterns("test_*", "__pycache__"))
            shutil.copy(HERE.parent.parent / ".context/templates/setup/tests/conftest_traceability.py", repo / "tests/conftest_traceability.py")
            write(repo / "tests/conftest.py", 'pytest_plugins = ["conftest_traceability"]\n')
            write(repo / "tests/test_ok.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/AC-01")\ndef test_ok(): pass\n')
            env = {**os.environ, "PYTHONDONTWRITEBYTECODE": "1"}
            def run(*extra):
                return subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", *extra, "tests"], cwd=str(repo), capture_output=True, text=True, env=env)
            r = run(); self.assertNotEqual(r.returncode, 0); self.assertIn("--strict-markers", r.stdout + r.stderr, "the plugin refuses to run without strict markers")
            r = run("--strict-markers"); self.assertEqual(r.returncode, 0, r.stdout + r.stderr)
            write(repo / "tests/test_ghost.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/TC-99")\ndef test_ghost(): pass\n')
            r = run("--strict-markers"); self.assertNotEqual(r.returncode, 0); self.assertIn("collection refused", r.stdout + r.stderr); self.assertIn("FEAT-001/TC-99", r.stdout + r.stderr)
            (repo / "tests/test_ghost.py").unlink()
            q = json.loads((repo / "config/quality.json").read_text()); q["traceability"] = {"required": False, "reason": "switched off"}; write(repo / "config/quality.json", json.dumps(q))
            r = run("--strict-markers"); self.assertEqual(r.returncode, 0, "required: false — the plugin does nothing, the suite runs")


class MiniYaml(unittest.TestCase):
    """The subset parser reads what this framework's frontmatter writes — flow mappings and lists included — so a project
    without PyYAML gets the same policy, never a silently empty roster."""

    def test_flow_collections_match_pyyaml(self):
        from gates.common import _mini_yaml
        text = RULE_AGENTS.split("---")[1]
        got = _mini_yaml(text)
        self.assertEqual(got["agents"]["roster"][0], {"name": "factory-dev-backend", "class": "worker", "surface": ["src/**"]})
        self.assertEqual(got["agents"]["classes"]["worker"]["tools"], {"must": ["Read", "Edit", "Write", "Bash"], "never": ["Agent"]})
        self.assertEqual(got["agents"]["tiers"], {"small": {"files": 5, "lines": 150, "turn_budget": 20, "probe_budget": 2}, "medium": {"turn_budget": 40, "probe_budget": 4}, "large": {"files": 30, "lines": 800, "turn_budget": 60, "probe_budget": 6}})
        self.assertEqual(got["agents"]["ladder"], {"critic": ["writer"], "writer": []})
        self.assertEqual(got["agents"]["resolve"][1], {"class": "plan-critic", "round": 2, "effort": "max"})
        self.assertEqual(_mini_yaml('x: [1, "a, b", {k: [true, null]}]')["x"], [1, "a, b", {"k": [True, None]}])
        try:
            import yaml
            self.assertEqual(got, yaml.safe_load(text), "the subset parser and PyYAML read the same structure")
        except ImportError:
            pass
        with self.assertRaisesRegex(GateFault, "unterminated"):
            _mini_yaml("x: [1, 2")

    def test_real_roster_without_pyyaml(self):
        """The delivered reader on the framework's own roster with PyYAML hidden: the validator is green and the spawn hook refuses — never a silently empty roster."""
        with tempfile.TemporaryDirectory() as tmp:
            write(Path(tmp) / "yaml.py", "raise ImportError('PyYAML hidden for the test')\n")
            env = {**os.environ, "PYTHONPATH": tmp, "PYTHONDONTWRITEBYTECODE": "1"}
            root = HERE.parent.parent; gate = str(HERE.parent / "gate.py")
            r = subprocess.run([sys.executable, gate, "--repo", str(root), "agents"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0, r.stdout + r.stderr)
            writer_alias = agents.policy(root)["families"]["writer"]   # whatever pair the repo configures: the writer's alias is the wrong one for a critic
            r = subprocess.run([sys.executable, gate, "--repo", str(root), "agents", "--spawn", "--agent", "factory-critic-security", "--model", writer_alias], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1, "a critic on the writer's alias is refused with the subset parser too"); self.assertIn("its family's alias", r.stdout)



class Scm(unittest.TestCase):
    """EVOL-054: the branch rule defended on the server — one reader, adapters per platform, RED on a missing setting, n/a where it cannot see.
    Every stub answers the repository probe first: a server the token cannot see is a fault, never four red findings about a branch nobody looked at."""

    FULL = [{"type": "non_fast_forward"}, {"type": "deletion"}, {"type": "pull_request", "parameters": {"required_approving_review_count": 0}},
            {"type": "required_status_checks", "parameters": {"required_status_checks": [{"context": "governance-check"}, {"context": "lockstep"}]}}]
    NEEDLES = ("pull request is not required", "force-push forbidden is not set", "deletion forbidden is not set")

    def _repo(self, tmp, platform="GitHub", approvals=0, checks=("governance-check",), required=True, branches=("main",)):
        os.makedirs(tmp, exist_ok=True)
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text())
        q["scm"] = {"required": required, "reason": "" if required else "no server", "platform": platform, "protected_branches": list(branches), "required_checks": list(checks), "approvals": approvals}
        write(repo / "config/quality.json", json.dumps(q)); return repo

    @staticmethod
    def _rs(rules, rid=7, enforcement="active", include=("~DEFAULT_BRANCH",), exclude=(), bypass=None, name="protect main"):
        return {"id": rid, "name": name, "enforcement": enforcement, "conditions": {"ref_name": {"include": list(include), "exclude": list(exclude)}}, "bypass_actors": bypass, "rules": rules}

    @staticmethod
    def _gh(rulesets=(), legacy=None, default="main", branches=("main",)):
        """The GitHub API as the adapter walks it: the repository, the branch, the rulesets list + detail, the legacy protection."""
        def fetch(url, headers, missing_ok=False):
            rest = url.split("/repos/acme/app", 1)[1].lstrip("/")
            if rest == "":
                return {"default_branch": default}
            if rest.startswith("branches/") and not rest.endswith("/protection"):
                b = urllib.parse.unquote(rest[len("branches/"):])
                if b in branches:
                    return {"name": b}
                if missing_ok:
                    return None
                raise GateFault(f"nothing at {url} (404)")
            if rest == "rulesets?targets=branch":
                return [{"id": r["id"]} for r in rulesets]
            if rest.startswith("rulesets/"):
                return next(r for r in rulesets if r["id"] == int(rest.split("/")[1]))
            if rest.endswith("/protection"):
                if legacy == "forbidden":
                    raise GateFault("the SCM API refused (403) — the token lacks the scope")
                return legacy
            raise AssertionError(url)
        return fetch

    def _findings_once(self, r, *needles):
        joined = " | ".join(r["findings"])
        for n in needles:
            self.assertEqual(joined.count(n), 1, f"{n!r} expected exactly once in {r['findings']}")

    def test_remote_and_tokens(self):
        r = scm.remote(Path("."), "git@github.com:acme/app.git"); self.assertEqual((r["host"], r["owner"], r["repo"]), ("github.com", "acme", "app"))
        r = scm.remote(Path("."), "https://gitlab.com/group/sub/proj.git"); self.assertEqual((r["owner"], r["repo"]), ("group/sub", "proj"))
        r = scm.remote(Path("."), "https://user@bitbucket.org/ws/slug"); self.assertEqual((r["host"], r["owner"], r["repo"]), ("bitbucket.org", "ws", "slug"))
        r = scm.remote(Path("."), "https://dev.azure.com/org/Proj/_git/repo"); self.assertEqual((r["owner"], r["project"], r["repo"]), ("org", "Proj", "repo"))
        r = scm.remote(Path("."), "git@ssh.dev.azure.com:v3/org/Proj/repo"); self.assertEqual((r["owner"], r["project"], r["repo"]), ("org", "Proj", "repo"))
        # a port is not an owner; the old visualstudio host; url-encoded segments; DefaultCollection
        r = scm.remote(Path("."), "ssh://git@github.com:2222/acme/app.git"); self.assertEqual((r["host"], r["owner"], r["repo"]), ("github.com", "acme", "app"))
        r = scm.remote(Path("."), "https://github.com:8443/acme/app.git"); self.assertEqual((r["host"], r["owner"], r["repo"]), ("github.com", "acme", "app"))
        r = scm.remote(Path("."), "https://org.visualstudio.com/Proj/_git/repo"); self.assertEqual((r["owner"], r["project"], r["repo"]), ("org", "Proj", "repo"))
        r = scm.remote(Path("."), "https://dev.azure.com/org/DefaultCollection/My%20Proj/_git/repo"); self.assertEqual((r["project"], r["repo"]), ("My Proj", "repo"))
        r = scm.remote(Path("."), "https://gitlab.com/g/my%20proj.git"); self.assertEqual(r["repo"], "my proj")
        with self.assertRaisesRegex(GateFault, "not one this reader understands"):
            scm.remote(Path("."), "nonsense")
        with self.assertRaisesRegex(GateFault, "names no owner/repo"):
            scm.remote(Path("."), "https://github.com/onlyowner")
        self.assertEqual(scm.token("GitHub", {"GH_TOKEN": "t"}), "t"); self.assertIsNone(scm.token("GitLab", {"GH_TOKEN": "t"})); self.assertIsNone(scm.token("Other", {}))

    def test_fetch_json_is_honest_about_every_error(self):
        import email.message
        import io
        from unittest import mock
        def http_error(code, headers=None):
            h = email.message.Message()
            for k, v in (headers or {}).items():
                h[k] = v
            return urllib.error.HTTPError("https://api.x/y?q=1", code, "msg", h, io.BytesIO(b""))
        with mock.patch.object(scm.time, "sleep"), mock.patch.object(scm.urllib.request, "urlopen") as uo:
            uo.return_value = io.BytesIO(b'{"a": 1}')
            self.assertEqual(scm.fetch_json("https://api.x/y", {}), {"a": 1})
            uo.side_effect = http_error(404)
            self.assertIsNone(scm.fetch_json("https://api.x/y", {}, missing_ok=True), "404 is an answer only where a missing thing is one")
            with self.assertRaisesRegex(GateFault, "not visible to this token, or origin names the wrong one"):
                scm.fetch_json("https://api.x/y", {})
            for code in (401, 403):
                uo.side_effect = http_error(code)
                with self.assertRaisesRegex(GateFault, "lacks the scope"):
                    scm.fetch_json("https://api.x/y", {})
            uo.reset_mock(); uo.side_effect = http_error(500)
            with self.assertRaisesRegex(GateFault, "transient: re-run"):
                scm.fetch_json("https://api.x/y?q=1", {})
            self.assertEqual(uo.call_count, 2, "a 5xx is retried once, then a fault")
            uo.reset_mock(); uo.side_effect = http_error(403, {"x-ratelimit-remaining": "0"})
            with self.assertRaisesRegex(GateFault, "transient"):
                scm.fetch_json("https://api.x/y", {})
            self.assertEqual(uo.call_count, 2, "a rate-limited 403 is not a scope error")
            uo.reset_mock(); uo.side_effect = urllib.error.URLError("refused")
            with self.assertRaisesRegex(GateFault, "could not be reached .* a fault, never a pass"):
                scm.fetch_json("https://api.x/y", {})
            self.assertEqual(uo.call_count, 2)

    def test_github_green_red_and_the_control_points(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, checks=("governance-check", "lockstep"))
            env = {"GH_TOKEN": "t"}; origin = "git@github.com:acme/app.git"
            gh = lambda *a, **k: self._gh(*a, **k)   # noqa: E731
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL)], legacy="forbidden"), env=env, origin=origin)
            self.assertTrue(r["ok"], r); self.assertEqual(r["status"], "ok"); self.assertEqual(r["repository"], "acme/app")
            b = r["branches"]["main"]
            self.assertEqual(b["checks"], ["governance-check", "lockstep"]); self.assertTrue(b["pr_required"] and b["force_push_blocked"] and b["deletion_blocked"]); self.assertEqual(b["approvals"], 0)
            self.assertEqual(b["unverifiable"], ["the bypass list (not exposed to this token)"], "bypass_actors absent from the payload = not exposed, listed")
            self.assertIn("scm-protection: ok", scm.render(r))
            # every missing setting is named exactly once: no PR rule, a check the server does not require, force-push and deletion open
            r = scm.check(repo, "ci", fetch=gh([self._rs([{"type": "required_status_checks", "parameters": {"required_status_checks": [{"context": "governance-check"}]}}], bypass=[])]), env=env, origin=origin)
            self.assertFalse(r["ok"]); self.assertEqual(r["status"], "RED"); self.assertEqual(len(r["findings"]), 4)
            self._findings_once(r, *self.NEEDLES, "not enforced by the server: lockstep")
            b = r["branches"]["main"]; self.assertFalse(b["pr_required"]); self.assertFalse(b["force_push_blocked"]); self.assertFalse(b["deletion_blocked"])
            self.assertIn("docs/scm/protection.md", r["reason"]); self.assertIn("RED", scm.render(r))
            repo2 = self._repo(tmp + "/x", approvals=2)
            r = scm.check(repo2, "ci", fetch=gh([self._rs(self.FULL)]), env=env, origin=origin); self.assertFalse(r["ok"]); self._findings_once(r, "0 approval(s) required, the project decided 2")
            # a ruleset in evaluation defends nothing; the legacy branch protection counts when present
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, enforcement="evaluate")]), env=env, origin=origin); self.assertFalse(r["ok"]); self.assertEqual(len(r["findings"]), 4)
            legacy = {"required_pull_request_reviews": {"required_approving_review_count": 0}, "required_status_checks": {"contexts": ["governance-check", "lockstep"]}, "allow_force_pushes": {"enabled": False}, "allow_deletions": {"enabled": False}}
            r = scm.check(repo, "ci", fetch=gh([], legacy=legacy), env=env, origin=origin); self.assertTrue(r["ok"], r)
            # the ruleset must reach the branch: an exclude, a scoped include, ~DEFAULT_BRANCH when the default is another branch — all RED; a glob include is honoured
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, include=("~ALL",), exclude=("refs/heads/main",))]), env=env, origin=origin); self.assertFalse(r["ok"], "excluded on the server = unprotected")
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, include=("refs/heads/release/*",))]), env=env, origin=origin); self.assertFalse(r["ok"], "a ruleset for release/* protects nothing on main")
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL)], default="develop"), env=env, origin=origin); self.assertFalse(r["ok"], "~DEFAULT_BRANCH is the server's default branch, not the configured one")
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, include=("refs/heads/ma*",))]), env=env, origin=origin); self.assertTrue(r["ok"], r)
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, include=("~ALL",))]), env=env, origin=origin); self.assertTrue(r["ok"], r)
            # a bypass actor is a hole with a name — RED; a pull-request-only bypass is not
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, bypass=[{"actor_id": 5, "actor_type": "Team", "bypass_mode": "always"}])]), env=env, origin=origin)
            self.assertFalse(r["ok"]); self._findings_once(r, "bypass actor(s)"); self.assertEqual(len(r["findings"]), 1)
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, bypass=[{"actor_id": 5, "bypass_mode": "pull_request"}])]), env=env, origin=origin); self.assertTrue(r["ok"], r); self.assertEqual(r["branches"]["main"]["unverifiable"], [])
            # a protected branch the server does not have protects nothing; two branches, one reached
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL)], branches=("develop",)), env=env, origin=origin); self.assertFalse(r["ok"]); self._findings_once(r, "does not exist on the server"); self.assertEqual(len(r["findings"]), 1)
            repo3 = self._repo(tmp + "/two", checks=("governance-check", "lockstep"), branches=("main", "release"))
            r = scm.check(repo3, "ci", fetch=gh([self._rs(self.FULL, include=("refs/heads/main",))], branches=("main", "release")), env=env, origin=origin)
            self.assertFalse(r["ok"]); self.assertTrue(r["findings"] and all(f.startswith("`release`") for f in r["findings"]), r["findings"]); self.assertIn("on main, release", r["reason"])
            # the control points: push and static never ask the server; ci without a token is n/a with the checklist, never green — unless the runner has one and hides it
            for cp in ("push", "static"):
                r = scm.check(repo, cp, fetch=gh([self._rs(self.FULL)]), env=env, origin=origin); self.assertTrue(r["ok"]); self.assertEqual(r["status"], "n/a"); self.assertIn("cannot see the server", r["reason"]); self.assertEqual(r["checklist"], scm.CHECKLIST)
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL)]), env={}, origin=origin); self.assertEqual(r["status"], "n/a"); self.assertIn("no GITHUB_TOKEN / GH_TOKEN", r["reason"]); self.assertIn("checklist:", scm.render(r))
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL)]), env={"GITHUB_ACTIONS": "true"}, origin=origin); self.assertFalse(r["ok"]); self.assertEqual(r["status"], "RED"); self.assertIn("does not export it", r["reason"]); self.assertIn("GH_TOKEN", r["reason"])
            # the config must name the host origin points at
            r = scm.check(self._repo(tmp + "/gl", platform="GitLab"), "ci", fetch=gh(), env={"GITLAB_TOKEN": "t"}, origin=origin); self.assertFalse(r["ok"]); self.assertIn("origin points at github.com (GitHub)", r["reason"])
            # an API error is a fault, never a pass; a missing config block is RED; required false needs its reason; Other is the checklist
            def boom(url, headers, missing_ok=False): raise GateFault("the SCM API answered 500")
            with self.assertRaisesRegex(GateFault, "500"):
                scm.check(repo, "ci", fetch=boom, env=env, origin=origin)
            q = json.loads((repo / "config/quality.json").read_text()); q["scm"]["platform"] = "Other"; q["scm"]["required_checks"] = []; write(repo / "config/quality.json", json.dumps(q))
            r = scm.check(repo, "ci", fetch=boom, env=env, origin=origin); self.assertEqual(r["status"], "n/a"); self.assertIn("no adapter", r["reason"])
            for block, needle in (({"required": False}, "without a `reason`"),
                                  ({"platform": "Gitea"}, "not one of"),
                                  ({"platform": "GitHub", "required_checks": []}, "required_checks is empty"),
                                  ({"platform": "GitHub", "required_checks": ["governance-check"], "approvals": True}, "must be an integer"),
                                  ({"platform": "GitHub", "required_checks": ["governance-check"], "protected_branches": "main"}, "non-empty list of branch names")):
                q["scm"] = block; write(repo / "config/quality.json", json.dumps(q))
                r = scm.check(repo, "ci", fetch=boom, env=env, origin=origin); self.assertFalse(r["ok"], block); self.assertIn(needle, r["reason"])
            q["scm"] = {"required": False, "reason": "no server"}; write(repo / "config/quality.json", json.dumps(q))
            r = scm.check(repo, "ci"); self.assertTrue(r["ok"]); self.assertEqual(r["status"], "n/a"); self.assertFalse(r["required"])
            del q["scm"]; write(repo / "config/quality.json", json.dumps(q))
            r = scm.check(repo, "ci"); self.assertFalse(r["ok"]); self.assertIn("`scm` is missing", r["reason"])

    def test_gitlab_adapter(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, platform="GitLab", approvals=1); env = {"GITLAB_TOKEN": "t"}; origin = "https://gitlab.com/g/p.git"
            def gl(protected, pipeline=True, rules=None):
                def fetch(url, headers, missing_ok=False):
                    if url.endswith("/projects/g%2Fp"): return {"only_allow_merge_if_pipeline_succeeds": pipeline}
                    if "/protected_branches/" in url:
                        if protected is None:
                            self.assertTrue(missing_ok); return None
                        return protected
                    if url.endswith("/approval_rules"):
                        if rules == "forbidden": raise GateFault("refused (403)")
                        return rules
                    raise AssertionError(url)
                return fetch
            # no one may push, force-push off, pipelines must succeed, one approval rule → green; a protected branch cannot be deleted
            r = scm.check(repo, "ci", fetch=gl({"push_access_levels": [{"access_level": 0}], "allow_force_push": False}, rules=[{"approvals_required": 1}]), env=env, origin=origin)
            self.assertTrue(r["ok"], r); self.assertTrue(r["branches"]["main"]["deletion_blocked"]); self.assertEqual(r["branches"]["main"]["checks"], ["pipeline must succeed"])
            # maintainers may push, force-push on, no pipeline rule, no approval rule → every setting named once
            r = scm.check(repo, "ci", fetch=gl({"push_access_levels": [{"access_level": 40}], "allow_force_push": True}, pipeline=False, rules=[]), env=env, origin=origin)
            self.assertFalse(r["ok"]); self._findings_once(r, "pull request is not required", "no pipeline / build is required", "force-push forbidden is not set", "0 approval(s) required, the project decided 1"); self.assertEqual(len(r["findings"]), 4)
            # the branch is not protected at all (404 = an answer here): pull request, force-push AND deletion red — never "unverifiable"
            r = scm.check(repo, "ci", fetch=gl(None, rules=[{"approvals_required": 1}]), env=env, origin=origin)
            self.assertFalse(r["ok"]); self._findings_once(r, *self.NEEDLES); self.assertEqual(r["unverifiable"], [])
            # approval rules refused (Free tier): not exposed, listed — never a fault, never red
            r = scm.check(repo, "ci", fetch=gl({"push_access_levels": [{"access_level": 0}], "allow_force_push": False}, rules="forbidden"), env=env, origin=origin)
            self.assertTrue(r["ok"], r); self.assertEqual(len(r["unverifiable"]), 1); self.assertIn("Premium", r["unverifiable"][0]); self.assertIn("not exposed by the API", r["reason"])

    def test_bitbucket_adapter(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, platform="Bitbucket", approvals=1); env = {"BITBUCKET_TOKEN": "u:p"}; origin = "git@bitbucket.org:ws/slug.git"
            def bb(values, model=None, pages=1):
                chunks = [values[i::pages] for i in range(pages)] if pages > 1 else [values]
                def fetch(url, headers, missing_ok=False):
                    if url.endswith("/repositories/ws/slug"): return {"slug": "slug"}
                    if url.endswith("/branching-model"):
                        self.assertTrue(missing_ok); return model
                    if "/branch-restrictions" in url:
                        n = int(url.split("page=")[1]) if "page=" in url else 0
                        page = {"values": chunks[n]}
                        if n + 1 < len(chunks): page["next"] = f"{url.split('&page=')[0]}&page={n + 1}"
                        return page
                    raise AssertionError(url)
                return fetch
            full = [{"kind": "push", "branch_match_kind": "glob", "pattern": "main", "users": [], "groups": []}, {"kind": "force", "branch_match_kind": "glob", "pattern": "main"}, {"kind": "delete", "branch_match_kind": "glob", "pattern": "main"},
                    {"kind": "require_passing_builds_to_merge", "branch_match_kind": "glob", "pattern": "main", "value": 1}, {"kind": "require_approvals_to_merge", "branch_match_kind": "glob", "pattern": "main", "value": 1},
                    {"kind": "enforce_merge_checks", "branch_match_kind": "glob", "pattern": "main"}]
            r = scm.check(repo, "ci", fetch=bb(full), env=env, origin=origin); self.assertTrue(r["ok"], r); self.assertEqual(r["branches"]["main"]["checks"], ["1 passing build(s)"]); self.assertEqual(r["branches"]["main"]["approvals"], 1)
            r = scm.check(repo, "ci", fetch=bb(full, pages=3), env=env, origin=origin); self.assertTrue(r["ok"], "the restrictions are paginated — every page is read")
            # a glob pattern Bitbucket honours; the branching-model kind resolved through the model (production = main, development = develop)
            r = scm.check(repo, "ci", fetch=bb([{**v, "pattern": "ma*"} for v in full]), env=env, origin=origin); self.assertTrue(r["ok"], r)
            model = {"production": {"branch": {"name": "main"}}, "development": {"branch": {"name": "develop"}}}
            bm = [{**v, "branch_match_kind": "branching_model", "branch_type": "production", "pattern": None} for v in full]
            r = scm.check(repo, "ci", fetch=bb(bm, model=model), env=env, origin=origin); self.assertTrue(r["ok"], r)
            r = scm.check(repo, "ci", fetch=bb([{**v, "branch_type": "development"} for v in bm], model=model), env=env, origin=origin); self.assertFalse(r["ok"], "restrictions on the development branch protect nothing on main")
            # without enforce_merge_checks the builds and approvals are advisory: a finding of their own, not a silent green
            r = scm.check(repo, "ci", fetch=bb(full[:-1]), env=env, origin=origin); self.assertFalse(r["ok"]); self._findings_once(r, "merge checks are advisory"); self.assertEqual(len(r["findings"]), 1); self.assertIn("approvals (merge checks not enforced)", " ".join(r["unverifiable"]))
            # nothing restricted: every setting named exactly once
            r = scm.check(repo, "ci", fetch=bb([]), env=env, origin=origin); self.assertFalse(r["ok"]); self._findings_once(r, *self.NEEDLES, "no pipeline / build is required"); self.assertEqual(len(r["findings"]), 4)

    def test_azure_adapter(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, platform="Azure DevOps", approvals=1); env = {"AZURE_DEVOPS_TOKEN": "pat"}; origin = "https://dev.azure.com/org/Proj/_git/repo"
            BUILD, REVIEWERS = "0609b952-1397-4640-95ec-e00a01b2c241", "fa4e907d-c16b-4a4c-9dfa-4906e5d171dd"
            def az(policies, default="refs/heads/main"):
                def fetch(url, headers, missing_ok=False):
                    if "/_apis/git/repositories/repo" in url: return {"id": "RID", "defaultBranch": default}
                    if "/_apis/policy/configurations" in url: return {"value": policies}
                    raise AssertionError(url)
                return fetch
            def pol(kind, scope, **kw):
                base = {"isEnabled": True, "isBlocking": True, "isDeleted": False}
                if kind == "build":
                    return {**base, "type": {"id": BUILD, "displayName": "Build"}, "settings": {"displayName": "governance-check", "scope": scope}, **kw}
                return {**base, "type": {"id": REVIEWERS, "displayName": "Minimum number of reviewers"}, "settings": {"minimumApproverCount": 1, "scope": scope}, **kw}
            exact = [{"repositoryId": "RID", "matchKind": "Exact", "refName": "refs/heads/main"}]
            r = scm.check(repo, "ci", fetch=az([pol("build", exact), pol("reviewers", exact)]), env=env, origin=origin)
            self.assertTrue(r["ok"], r); self.assertEqual(len(r["unverifiable"]), 2); self.assertIn("not exposed by the API", r["reason"]); self.assertEqual(r["branches"]["main"]["checks"], ["governance-check"])
            # the scope shapes Azure has: Prefix, DefaultBranch, a null repositoryId (project-wide); another repository's policy is not this one's
            for scope in ([{"repositoryId": "RID", "matchKind": "Prefix", "refName": "refs/heads/ma"}], [{"repositoryId": None, "matchKind": "DefaultBranch", "refName": None}], [{"repositoryId": None, "matchKind": "Exact", "refName": "refs/heads/main"}]):
                r = scm.check(repo, "ci", fetch=az([pol("build", scope), pol("reviewers", scope)]), env=env, origin=origin); self.assertTrue(r["ok"], (scope, r))
            other = [{"repositoryId": "OTHER", "matchKind": "Exact", "refName": "refs/heads/main"}]
            r = scm.check(repo, "ci", fetch=az([pol("build", other), pol("reviewers", other)]), env=env, origin=origin); self.assertFalse(r["ok"], "another repository's policy protects nothing here")
            r = scm.check(repo, "ci", fetch=az([pol("build", exact), pol("reviewers", exact)], default="refs/heads/develop"), env=env, origin=origin); self.assertTrue(r["ok"], "Exact scope does not depend on the default branch")
            r = scm.check(repo, "ci", fetch=az([pol("build", [{"repositoryId": None, "matchKind": "DefaultBranch"}])], default="refs/heads/develop"), env=env, origin=origin); self.assertFalse(r["ok"], "DefaultBranch scope on a server whose default is develop")
            # a non-blocking, a disabled or a deleted policy defends nothing; a displayName-only type still resolves
            for kw in ({"isBlocking": False}, {"isEnabled": False}, {"isDeleted": True}):
                r = scm.check(repo, "ci", fetch=az([pol("build", exact, **kw), pol("reviewers", exact, **kw)]), env=env, origin=origin); self.assertFalse(r["ok"], kw)
            legacy = [{"isEnabled": True, "isBlocking": True, "type": {"displayName": "Build"}, "settings": {"displayName": "governance-check", "scope": [{"refName": "refs/heads/main"}]}},
                      {"isEnabled": True, "isBlocking": True, "type": {"displayName": "Minimum number of reviewers"}, "settings": {"minimumApproverCount": 1, "scope": [{"refName": "refs/heads/main"}]}}]
            r = scm.check(repo, "ci", fetch=az(legacy), env=env, origin=origin); self.assertTrue(r["ok"], r)
            r = scm.check(repo, "ci", fetch=az([]), env=env, origin=origin); self.assertFalse(r["ok"]); self._findings_once(r, "pull request is not required", "not enforced by the server: governance-check"); self.assertEqual(len(r["findings"]), 2, "force-push and deletion are permissions — unverifiable, never red")

    def test_scm_protection_is_a_light_member_run_at_ci(self):
        """The member and its runner: the control point token reaches the reader (drop it and CI would say 'cannot see the server' forever)."""
        from unittest import mock
        self.assertIn("scm-protection", {m["member"] for m in profile.owed("light")})
        runner = next(m[4] for m in profile.MEMBERS if m[0] == "scm-protection")
        self.assertEqual(profile._cmd(Path("."), runner, "origin/main", "b", "ci")[-2:], ["--control-point", "ci"])
        with tempfile.TemporaryDirectory() as tmp:
            repo = Profile()._repo(tmp, mode="production")
            q = json.loads((repo / "config/quality.json").read_text())
            q["scm"] = {"platform": "GitHub", "protected_branches": ["main"], "required_checks": ["governance-check"], "approvals": 0}
            write(repo / "config/quality.json", json.dumps(q))
            subprocess.run(["git", "-C", str(repo), "remote", "add", "origin", "git@github.com:acme/app.git"], check=True)
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/F-002-x"], check=True)
            with mock.patch.dict(os.environ, {"GITHUB_ACTIONS": "true", "GH_TOKEN": "", "GITHUB_TOKEN": ""}):
                rep = profile.run(repo, base="origin/main", control_point="ci", only=["scm-protection"])
                by = {r["member"]: r for r in rep["results"]}
                self.assertEqual(by["scm-protection"]["status"], "RED", by); self.assertIn("does not export it", by["scm-protection"]["tail"], "at ci the reader ran at ci: the runner's hidden token is the finding — never 'cannot see the server'")
                rep = profile.run(repo, base="origin/main", control_point="push", only=["scm-protection"])
                by = {r["member"]: r for r in rep["results"]}
                self.assertEqual(by["scm-protection"]["status"], "n/a"); self.assertIn("cannot see the server", by["scm-protection"]["tail"])


